-- docunavi PostgreSQL schema (Prisma Postgres, Tokyo). DRAFT - not applied. Hand-written SQL migration; the runner wraps each file in one transaction.
-- Port of workers/api/migrations/0001_schema.sql (D1 / SQLite), which stays untouched until the cutover.
-- Conversions: AUTOINCREMENT -> GENERATED BY DEFAULT AS IDENTITY (explicit ids allowed so D1 ids, incl. the Vectorize id, survive an import);
--   INTEGER unix ms -> timestamptz; GLOB -> regex (~); base64 checkpoint blobs -> bytea; chunks.embedding vector(768) is back (pgvector).
-- Better Auth keeps its camelCase column names, so they are double-quoted everywhere.

CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE document_collections (
  name        text PRIMARY KEY CHECK (name ~ '^[a-zA-Z0-9_-]{1,40}$'),
  label       text NOT NULL,
  description text NOT NULL DEFAULT '',
  sort_order  integer NOT NULL DEFAULT 0,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE document_targets (
  name        text PRIMARY KEY CHECK (name ~ '^[a-z0-9_-]{1,40}$'),
  label       text NOT NULL,
  description text NOT NULL DEFAULT '',
  sort_order  integer NOT NULL DEFAULT 0,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE document_types (
  name        text PRIMARY KEY CHECK (name ~ '^[a-z0-9_-]{1,40}$'),
  label       text NOT NULL,
  description text NOT NULL DEFAULT '',
  sort_order  integer NOT NULL DEFAULT 0,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE documents (
  id             bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  source         text NOT NULL UNIQUE,
  content_hash   text NOT NULL,
  status         text NOT NULL CHECK (status IN ('ready', 'failed', 'processing')),
  failure_reason text,
  pages          integer NOT NULL DEFAULT 0,
  title          text,
  collection     text CHECK (collection IS NULL OR collection ~ '^[A-Za-z0-9_-]{1,40}$'),
  target         text REFERENCES document_targets (name) ON UPDATE RESTRICT ON DELETE RESTRICT,
  doc_type       text REFERENCES document_types (name) ON UPDATE RESTRICT ON DELETE RESTRICT,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX documents_collection_idx ON documents (collection);
CREATE INDEX documents_target_idx ON documents (target);

CREATE TABLE chunks (
  id                   bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, -- also the Vectorize vector id (stringified) while Vectorize is in use
  document_id          bigint NOT NULL REFERENCES documents (id) ON DELETE CASCADE,
  chunk_index          integer NOT NULL,
  page                 integer NOT NULL,
  page_end             integer,
  kind                 text NOT NULL DEFAULT 'text',
  heading              text,
  content              text NOT NULL,
  content_hash         text NOT NULL,
  embedding_model      text,
  embedding_dimensions integer,
  embedding_input_hash text,
  embedding            vector(768), -- NULL until embedded. No vector index on purpose: exact scan is right at this size (HNSW was unused at 421 chunks)
  created_at           timestamptz NOT NULL DEFAULT now(),
  UNIQUE (document_id, chunk_index)
);

CREATE TABLE document_images (
  id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  document_id   bigint NOT NULL REFERENCES documents (id) ON DELETE CASCADE,
  kind          text NOT NULL DEFAULT 'hero' CHECK (kind = 'hero'),
  status        text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'approved', 'rejected')),
  mime_type     text NOT NULL,
  r2_key        text NOT NULL UNIQUE,
  byte_size     integer NOT NULL CHECK (byte_size BETWEEN 1 AND 5242880),
  width         integer,
  height        integer,
  document_hash text,
  prompt_sha256 text NOT NULL CHECK (prompt_sha256 ~ '^[0-9a-f]{64}$'),
  model         text NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  approved_at   timestamptz
);
-- at most one approved hero per document
CREATE UNIQUE INDEX document_images_one_approved ON document_images (document_id, kind) WHERE status = 'approved';

-- Better Auth (core + jwt plugin). Column names are the camelCase names Better Auth uses (quoted). Defined before user_roles, which references "user".
CREATE TABLE "user" (
  id              text PRIMARY KEY,
  name            text NOT NULL,
  email           text NOT NULL UNIQUE,
  "emailVerified" boolean NOT NULL DEFAULT false,
  image           text,
  "createdAt"     timestamptz NOT NULL DEFAULT now(),
  "updatedAt"     timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE session (
  id          text PRIMARY KEY,
  "expiresAt" timestamptz NOT NULL,
  token       text NOT NULL UNIQUE,
  "createdAt" timestamptz NOT NULL DEFAULT now(),
  "updatedAt" timestamptz NOT NULL DEFAULT now(),
  "ipAddress" text,
  "userAgent" text,
  "userId"    text NOT NULL REFERENCES "user" (id) ON DELETE CASCADE
);
CREATE INDEX "session_userId_idx" ON session ("userId");

CREATE TABLE account (
  id                      text PRIMARY KEY,
  "accountId"             text NOT NULL,
  "providerId"            text NOT NULL,
  "userId"                text NOT NULL REFERENCES "user" (id) ON DELETE CASCADE,
  "accessToken"           text,
  "refreshToken"          text,
  "idToken"               text,
  "accessTokenExpiresAt"  timestamptz,
  "refreshTokenExpiresAt" timestamptz,
  scope                   text,
  password                text,
  "createdAt"             timestamptz NOT NULL DEFAULT now(),
  "updatedAt"             timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX "account_userId_idx" ON account ("userId");

CREATE TABLE verification (
  id          text PRIMARY KEY,
  identifier  text NOT NULL,
  value       text NOT NULL,
  "expiresAt" timestamptz NOT NULL,
  "createdAt" timestamptz NOT NULL DEFAULT now(),
  "updatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX verification_identifier_idx ON verification (identifier);

CREATE TABLE jwks (
  id          text PRIMARY KEY,
  "publicKey"  text NOT NULL,
  "privateKey" text NOT NULL,
  alg         text,
  crv         text,
  "createdAt" timestamptz NOT NULL DEFAULT now(),
  "expiresAt" timestamptz
);

CREATE TABLE roles (
  name  text PRIMARY KEY,
  label text NOT NULL
);

CREATE TABLE role_collection_access (
  role       text NOT NULL REFERENCES roles (name) ON DELETE CASCADE,
  collection text NOT NULL,
  PRIMARY KEY (role, collection)
);

-- user_id = Better Auth user.id
CREATE TABLE user_roles (
  user_id text NOT NULL REFERENCES "user" (id) ON DELETE CASCADE,
  role    text NOT NULL REFERENCES roles (name) ON DELETE RESTRICT,
  PRIMARY KEY (user_id, role)
);

CREATE TABLE access_audit (
  id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  at         timestamptz NOT NULL DEFAULT now(),
  actor      text NOT NULL,
  table_name text NOT NULL,
  op         text NOT NULL,
  row_data   jsonb
);

-- LangGraph checkpointer (same shape as langgraph-checkpoint-sqlite; serialized blobs are bytea again, no base64; metadata is jsonb)
CREATE TABLE checkpoints (
  thread_id            text NOT NULL,
  checkpoint_ns        text NOT NULL DEFAULT '',
  checkpoint_id        text NOT NULL,
  parent_checkpoint_id text,
  type                 text,
  checkpoint           bytea NOT NULL,
  metadata             jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at           timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (thread_id, checkpoint_ns, checkpoint_id)
);
CREATE INDEX checkpoints_thread_idx ON checkpoints (thread_id, created_at);

CREATE TABLE checkpoint_writes (
  thread_id     text NOT NULL,
  checkpoint_ns text NOT NULL DEFAULT '',
  checkpoint_id text NOT NULL,
  task_id       text NOT NULL,
  idx           integer NOT NULL,
  channel       text NOT NULL,
  type          text,
  value         bytea,
  PRIMARY KEY (thread_id, checkpoint_ns, checkpoint_id, task_id, idx)
);
